UPDATE businesses SET description = 'Woolworths Brackenfell Corner is a Woolworths Food store in Brackenfell Corner Shopping Centre, on the corner of Frans Conradie Drive and Paradys Street near St Michaels. As one of the main stores in the open-air centre, it serves Brackenfell households who want good-quality groceries without a long trip.

Fresh food is the focus, with organic fruit and vegetables, sustainably sourced meat and other proteins, and a wide choice of ready-made meals for quick weeknight suppers. An in-store bakery offers fresh bread and pastries, and a coffee station lets shoppers pick up a drink on the way in or out. The store is neatly organised, which makes it easy for shoppers to find what they need on a short visit, and it keeps longer trading hours over the weekend. For a quick, well-stocked food shop close to home, it is a convenient local stop. Woolworths is at Shop 1, Brackenfell Corner Shopping Centre, corner Frans Conradie Drive and Paradys Street, Brackenfell.', description_enriched_at = datetime('now') WHERE slug = 'woolworths-brackenfell-corner-brackenfell' AND description = 'Woolworths Brackenfell Corner is a Woolworths supermarket inside Brackenfell Corner Shopping Centre in Brackenfell.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
